body { margin: 0; font: 16px sans-serif; background: #fff; color: #111 }
header { height: 56px; display: flex; align-items: center; gap: 12px; padding: 0 16px; border-bottom: 1px solid #ddd; margin-bottom: 16px }
header h1 { font-size: 20px; margin: 0 }
header input { flex: 1; max-width: 360px }
.page { display: flex; gap: 24px; padding: 0 16px }
.main { flex: 1; min-width: 0 }
video { width: 640px; height: 360px; background: #000; display: block }
.bar { display: flex; gap: 12px; align-items: center; width: 640px }
.track { flex: 1; height: 6px; background: #ccc }
#done { height: 6px; width: 0; background: #c00 }
#related { width: 280px; flex: none; list-style: none; margin: 0; padding: 0 }
#related li { margin-bottom: 8px }
#related img { display: block }
#comments { list-style: none; padding: 0 }

const video = document.getElementById('card');
const clock = document.getElementById('clock');
const done = document.getElementById('done');
const pad = s => String(Math.floor(s)).padStart(2, '0');
video.addEventListener('timeupdate', () => {
  const d = video.duration || 4;
  clock.textContent = `0:${pad(video.currentTime)} / 0:${pad(d)}`;
  done.style.width = `${(100 * video.currentTime / d).toFixed(1)}%`;
});
document.getElementById('toggle').addEventListener('click', e => {
  if (video.paused) { video.play(); e.target.textContent = 'Pause'; }
  else { video.pause(); e.target.textContent = 'Play'; }
});
